/** edited: lista sendo editada (vem preenchida com a senha; ao entrar, os dados novos ficam no lugar dela). */
function showLogin(msg, serverValue, userValue, back, edited, passValue) {
  const acc = store.get('account', {});
  if (serverValue === undefined) { serverValue = acc.server; userValue = acc.user; }
  const root = screenEl();
  root.innerHTML =
    '<div class="login"><div class="logo big">' + LOGO + '</div>' +
    '<div class="lsub">Entre com a sua conta Xtream Codes ou cole o link M3U no primeiro campo</div>' +
    '<input class="fld f" id="srv" placeholder="Endereço do servidor ou link M3U da lista" autocomplete="off" spellcheck="false">' +
    '<input class="fld f" id="usr" placeholder="Usuário" autocomplete="off" spellcheck="false">' +
    '<input class="fld f" id="pwd" placeholder="Senha" autocomplete="off" spellcheck="false">' +
    '<div class="msg"></div><div class="btn f" id="go">Entrar</div>' +
    '<div class="note">O NEXO TV é apenas um player. Nenhum canal ou conteúdo está incluso.</div></div>';
  const $ = id => root.querySelector('#' + id);
  $('srv').value = serverValue || ''; $('usr').value = userValue || '';
  $('pwd').value = passValue || (edited && edited.pass) || '';
  root.querySelector('.msg').textContent = msg || '';
  // link M3U do painel: longo …/get.php?username=U&password=S  ·  curto …/p/U/S/m3u (pode ser outro host, que redireciona ao painel)
  let shortLink = null;
  const fromLink = t => {
    t = (t == null ? $('srv').value : t).trim();
    const m = /^(?:(https?):\/\/)?([^/?#]+)([^?#]*)(?:\?([^#]*))?/i.exec(t);
    if (!m) return false;
    const q = {};
    (m[4] || '').split('&').forEach(p => { const kv = p.split('='); if (kv[0]) q[decodeURIComponent(kv[0])] = decodeURIComponent((kv[1] || '').replace(/\+/g, ' ')); });
    let u = q.username, p = q.password;
    if (!u || !p) {
      const seg = m[3].split('/').filter(Boolean), i = seg.indexOf('p');
      if (i < 0 || seg.length <= i + 2) return false;
      u = decodeURIComponent(seg[i + 1]); p = decodeURIComponent(seg[i + 2]); shortLink = (m[1] ? '' : 'http://') + t;
    }
    $('srv').value = (m[1] || 'http') + '://' + m[2]; $('usr').value = u; $('pwd').value = p;
    return true;
  };
  $('srv').addEventListener('blur', () => fromLink());
  const submit = () => {
    fromLink();
    const s = $('srv').value, u = $('usr').value.trim(), p = $('pwd').value, short = shortLink;
    if (!s.trim() || !u || !p) { root.querySelector('.msg').textContent = 'Preencha servidor, usuário e senha.'; return; }
    if (!short) return connect(s, u, p, edited, true);
    // o link curto costuma redirecionar para o get.php do painel: é de lá que vem o servidor certo
    root.querySelector('.msg').textContent = 'Lendo o link…';
    shortLink = null;
    timeout(fetch(short), 15000).then(r => { const final = r.url; if (r.body && r.body.cancel) r.body.cancel(); if (final && final !== short) fromLink(final); })
      .catch(() => {}).then(() => connect($('srv').value, $('usr').value.trim(), $('pwd').value, edited, true));
  };
  $('pwd')._enter = submit;
  $('go').addEventListener('click', submit);
  show(root, focusScreen(root, serverValue && userValue ? $('pwd') : $('srv'), back || exitApp));
  phoneQr(root, d => {
    // servidor digitado no campo "Link M3U" do celular é comum: usuário/senha valem também (fromLink só os troca se o link os tiver)
    $('srv').value = d.link || d.server || ''; $('usr').value = d.user || ''; $('pwd').value = d.pass || '';
    submit();
  });
}
/** QR para cadastrar pelo celular: o serviço do pacote (services/phone) abre a porta na rede de casa; só existe na TV. */
let phoneBridge = null;
function phoneQr(root, received) {
  if (typeof qrcode === 'undefined') return;
  if (typeof PalmServiceBridge === 'undefined') return relayQr(root, received);
  const id = screenId, b = new PalmServiceBridge();
  phoneBridge = b;
  b.onservicecallback = m => {
    let r; try { r = JSON.parse(m); } catch (e) { return; }
    if (id !== screenId || !r.returnValue) return;
    if (r.data) return received(r.data);
    if (!r.url || root.querySelector('.qside')) return;
    drawQr(root, r.url, 'O celular precisa estar no mesmo Wi-Fi da TV.', r.url.split('/?')[0]);
  };
  b.call('luna://com.nexotv.player.phone/start', '{"subscribe":true}');
}
function drawQr(root, url, hint, label) {
  const q = qrcode(0, 'M'); q.addData(url); q.make();
  const n = q.getModuleCount(), cv = document.createElement('canvas'), g = cv.getContext('2d');
  cv.width = cv.height = n + 4; g.fillStyle = '#fff'; g.fillRect(0, 0, n + 4, n + 4); g.fillStyle = '#000';
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (q.isDark(y, x)) g.fillRect(x + 2, y + 2, 1, 1);
  const side = el('div', 'qside', '<b>Pelo celular</b><p>Aponte a câmera para o código.\n' + hint + '</p>');
  side.appendChild(cv);
  side.appendChild(el('small', '', esc(label)));
  root.querySelector('.login').classList.add('wq');
  root.appendChild(side);
}
/** Samsung (sem serviço local): o celular abre a página fixa PHONE_PAGE, cifra com a chave do QR (#k, nunca sai do
 *  aparelho) e manda para ntfy.sh/<tópico aleatório>; a TV escuta o tópico por SSE e decifra. Fonte: celular/index.html. */
const PHONE_PAGE = 'https://lanicchio.github.io/nexo-tv-celular/';
function relayQr(root, received) {
  if (!(window.crypto && crypto.subtle && window.EventSource)) return;
  const b64 = a => btoa(String.fromCharCode.apply(null, a)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  const abc = 'abcdefghijklmnopqrstuvwxyz0123456789', raw = crypto.getRandomValues(new Uint8Array(24));
  const topic = 'nexotv' + Array.from(raw, x => abc[x % 36]).join(''), keyRaw = crypto.getRandomValues(new Uint8Array(16));
  const id = screenId, es = new EventSource('https://ntfy.sh/' + topic + '/sse');
  phoneBridge = { cancel: () => es.close() };
  let got = false;
  es.onmessage = ev => {
    let m; try { m = JSON.parse(ev.data); } catch (e) { return; }
    if (got || id !== screenId || m.event !== 'message' || !m.message) return;
    const all = Uint8Array.from(atob(m.message), c => c.charCodeAt(0));
    crypto.subtle.importKey('raw', keyRaw, 'AES-GCM', false, ['decrypt'])
      .then(k => crypto.subtle.decrypt({ name: 'AES-GCM', iv: all.slice(0, 12) }, k, all.slice(12)))
      .then(p => { const d = JSON.parse(new TextDecoder().decode(p)); if (got || id !== screenId) return; got = true; es.close(); received(d); })
      .catch(() => {}); // lixo no tópico (não cifrado com a nossa chave): ignora
  };
  drawQr(root, PHONE_PAGE + '#t=' + topic + '&k=' + b64(keyRaw), 'Funciona com o celular em qualquer internet.', PHONE_PAGE.replace('https://', '').replace(/\/$/, ''));
}

