  } else {
    root.innerHTML = '<div class="lh vod"><div class="hb hcat">' + ic(kind === 'series' ? 'series' : 'grid', 'g') + '<b class="ttl">' + K.title + '</b></div>' +
      '<div class="hb htit">' + ic('search', 'hsi') + '<input class="hin" autocomplete="off" spellcheck="false"><b class="ttl"></b><span class="cnt"></span></div>' +
      '<div class="hb hsort vview"></div></div>' +
