  const hin = $('.hin');
  hin.placeholder = live ? 'Digite o nome do canal' : kind === 'movie' ? 'Digite o nome do filme' : 'Digite o nome da série';
  const sortNames = ['Organizar', 'Nome A–Z', 'Nome Z–A'];
  if (live) $('.hsort span').textContent = sortNames[sortMode];

  const activate = c => {
    col = c;
    catL.active = c === 'cats'; itemL.active = c === 'items'; epgL.active = c === 'epg'; dayL.active = c === 'days';
    if (c !== 'items') itemL.side = false;
    catL.draw(); itemL.draw();
