    epgL.set(progs.length ? progs.map(p => ({ title: p.title, h: hhmm(p.start) + ' – ' + hhmm(p.end), dot: now >= p.start && now < p.end ? '#22c55e' : '#8fa3d6' }))
      : [{ title: epgAll.length ? 'Sem programação neste dia' : 'Sem programação para este canal' }],
