  }
  const epgMessage = m => epgL.set([{ title: m }]);

  const placePreview = () => { const r = rectOf($('.lprev')); placeVideo({ x: r.x + 6, y: r.y + 6, w: r.w - 12, h: r.h - 12 }); };
  const startPreview = pos => {
    const ch = items[pos];
