    const lg = $('.pband img'); lg.style.visibility = ch.icon ? '' : 'hidden'; if (ch.icon) lg.src = ch.icon; else lg.removeAttribute('src');
    loadEpg(ch.id, 0, progs => {
      if (previewId !== ch.id || !$('.pepg')) return;
      const now = Date.now(), cur = progs.filter(p => now >= p.start && now < p.end)[0];
      const next = progs.filter(p => p.start >= (cur ? cur.end : now))[0];
      $('.pepg').innerHTML = [cur, next].filter(Boolean).map(p => '<div>' + hhmm(p.start) + '  ' + esc(p.title) + '</div>').join('');
    });
    if (!isBlocked(ch)) store.set('last:' + acct(), ch); // canal bloqueado não vira "Continuar"
    onVideoState = t => { const s = $('.pstat'); if (s) s.textContent = t === 'fail' ? 'Não foi possível reproduzir este canal.' : t; };
    // a tela cheia só amplia o mesmo vídeo da telinha, sem abrir o canal de novo
    if (!playing || playing.id !== ch.id) playUrls(ch.id, api.liveUrls(ch.id));
