    itemL.mark = pos; itemL.draw(true);
  };
  const fullscreen = () => play(kind, zap, zapAt, -1, (at, list) => showBrowse(kind, previewKey, at, true), true);

  const message = m => { items = []; itemL.set([{ name: m }]); };
  const vodRight = () => { if (!live) { catRight = cats.map(c => c.id === FAV ? visible(favs(kind)).length : c.id === SEARCH ? 'search' : ''); catL.draw(true); } };
  const showCounts = all => {
    const vis = visible(all), by = {};
    vis.forEach(it => { by[it.cat] = (by[it.cat] || 0) + 1; });
    catRight = cats.map(c => c.id === ALL ? vis.length : c.id === FAV ? visible(favs()).length : c.id === SEARCH ? 'search' : (by[c.id] || 0));
