  };
  const showList = (all, focus, select) => {
    let list = visible(all);
    if (live && sortMode) list = list.slice().sort((a, b) => { const x = a.name.toLowerCase(), y = b.name.toLowerCase(); return (x < y ? -1 : x > y ? 1 : 0) * (sortMode === 1 ? 1 : -1); });
