  let afterLoad = null; // voltou da tela cheia antes da lista chegar: continua o canal na telinha quando ela chegar
  // restore: reabrindo a tela (voltou de um resultado/tela cheia) mostra a última busca sem abrir o pop-up
  const load = (pos, focus, select, restore) => {
    const key = cats[pos].id;
