    }
    if (key === FAV) return showList(favs(kind), focus, select);
    const q = srch ? (searchQ[kind] || '').trim() : '';
    if (srch && q.length < 2) {
      items = []; setStatus('');
      if (live) message('Digite pelo menos 2 letras lá em cima'); else { itemL.empty = 'Digite pelo menos 2 letras lá em cima.'; itemL.set([]); }
      return;
    }
    // busca só no tipo desta tela, na lista inteira ("Todos"); nome sem acento guardado no item
    const words = srch ? norm(q).split(' ').filter(Boolean) : null;
    const pick = l => !words ? l : l.filter(it => { const n = it._n || (it._n = norm(it.name)); return words.every(w => n.indexOf(w) >= 0); }).slice(0, MAX_RESULTS);
    const whole = words || key === ALL, ck = kind + ':' + (whole ? ALL : key);
    if (live && whole && itemCache[ck]) showCounts(itemCache[ck]);
    if (itemCache[ck]) return showList(pick(itemCache[ck]), focus, select);
    if (live) { setStatus('…'); message(words ? 'Buscando…' : 'Carregando canais…'); } else { items = []; itemL.set([]); setStatus(words ? 'Buscando…' : 'Carregando ' + K.noun + '…'); }
    const id = screenId;
    // digitando durante o 1º download: um pedido só da lista inteira
    (pending[ck] || (pending[ck] = api.items(kind, whole ? null : key).then(l => { delete pending[ck]; return l; }, e => { delete pending[ck]; throw e; }))).then(l => {
      if (id !== screenId || current !== pos) return;
      itemCache[ck] = l;
      if (live && whole) showCounts(l);
      showList(pick(l), focus, select);
      if (afterLoad) { const f = afterLoad; afterLoad = null; f(); }
    }).catch(e => { if (id !== screenId) return; if (afterLoad) { afterLoad = null; stopVideo(); } if (live) message(e.message); else setStatus(e.message); });
  };

  // programação do canal em foco; espera o D-pad parar para não disparar uma requisição por linha
  let epgTimer = 0;
  const epgFor = ch => {
    clearTimeout(epgTimer);
    if (!live || !ch || !ch.id) return;
    epgMessage('Carregando programação…');
    epgTimer = setTimeout(() => loadEpg(ch.id, 0, l => { const c = itemL.cur(); if (c && c.id === ch.id && $('.lepg')) { epgAll = l; showDay(); } }), 350);
  };
  itemL.onMove = ch => epgFor(ch);

  const toggle = () => {
    const it = itemL.cur();
    if (!it || !it.id) return;
    toggleFav(it, kind);
    if (cats[current].id === FAV) showList(favs(kind), false, itemL.idx); else itemL.draw(true);
    if (live && itemCache['live:' + ALL]) showCounts(itemCache['live:' + ALL]); else vodRight();
  };
  const openItem = () => {
    const it = itemL.cur(), key = cats[current].id, pos = itemL.idx;
    if (!it || !it.id) return; // linha de aviso
    if (live) { if (playing && previewId === it.id) return fullscreen(); return startPreview(pos); }
    if (kind === 'movie') showMovie(it, () => showBrowse(kind, key, pos));
    else showSeries(it, () => showBrowse(kind, key, pos));
  };
  const hasPreview = () => live && playing && previewId != null;

  const handler = {
    key(k) {
      if (k === 'back' && col !== 'input') return showHome();
      const L = col === 'cats' ? catL : col === 'items' ? itemL : col === 'epg' ? epgL : col === 'days' ? dayL : null;
      if (col === 'sort') {
        if (k === 'ok') { sortMode = (sortMode + 1) % 3; $('.hsort span').textContent = sortNames[sortMode]; if (current >= 0) load(current, false, 0); }
        if (k === 'down') activate(items.length ? 'items' : 'cats');
        if (k === 'left') activate('cats');
        return;
      }
      if (col === 'input') {
        if (k === 'down' || k === 'ok') { if (items.length) activate('items'); else if (k === 'ok') hin.focus(); }
        else if (k === 'left' || k === 'back') activate('cats');
        return;
      }
      if (col === 'view') {
        if (k === 'ok') { store.set('vodList', !store.get('vodList', false)); return showBrowse(kind, cats[current] ? cats[current].id : null, itemL.idx); }
        if (k === 'down') activate(items.length ? 'items' : 'cats');
        if (k === 'left') activate('cats');
        return;
      }
      if (col === 'prev') {
        if (k === 'ok') return fullscreen();
        if (k === 'left') return activate('items');
        if (k === 'down') return activate('epg');
        return;
      }
      if (k === 'chup' || k === 'chdown') return L.move((k === 'chup' ? -1 : 1) * L.page());
      if (k === 'up' || k === 'down') {
        const d = k === 'up' ? -1 : 1;
        if (L.move(d * L.cols)) return;
        if (k === 'up' && (col === 'items' || col === 'cats') && cats[current].id === SEARCH) return activate('input');
        if (k === 'up' && (col === 'cats' || col === 'items')) return activate(live ? 'sort' : 'view');
        if (k === 'up' && col === 'epg' && hasPreview()) return activate('prev');
        return;
      }
      if (col === 'cats') {
        if (k === 'right' && items.length) activate('items');
        else if (k === 'ok') { if (catL.idx !== current || cats[catL.idx].id === SEARCH) load(catL.idx, true); } // OK no grupo já aberto não faz nada (Buscar reabre o pop-up)
        return;
      }
      if (col === 'items') {
        if (!live) { // grade de capas
          if (k === 'left') { if (itemL.idx % itemL.cols === 0) activate('cats'); else itemL.move(-1); }
          else if (k === 'right') { if ((itemL.idx + 1) % itemL.cols) itemL.move(1); }
          else if (k === 'ok') openItem();
          else if (k === 'yellow' || k === 'menu') toggle();
          return;
        }
        // ▶ leva o cursor para a ☆ da mesma linha (OK favorita); ▶ de novo segue para a telinha/programação; ◀ volta
        if (k === 'left') { if (itemL.side) { itemL.side = false; itemL.draw(); } else activate('cats'); return; }
        if (k === 'right') {
          if (!itemL.side && items.length) { itemL.side = true; itemL.draw(); return; }
          return activate(hasPreview() ? 'prev' : 'epg');
        }
        if (k === 'ok') return itemL.side ? toggle() : openItem();
        if (k === 'yellow' || k === 'menu') return toggle();
        return;
      }
      if (col === 'epg') { if (k === 'left') activate('items'); else if (k === 'right') activate('days'); return; }
      if (col === 'days') {
        if (k === 'left') activate('epg');
        else if (k === 'ok') { day = dayL.idx; showDay(); }
      }
    }
  };
  const handlerClicks = () => {
    catL.onClick = i => { activate('cats'); if (i !== current || cats[i].id === SEARCH) load(i, true); };
    itemL.onClick = () => { activate('items'); openItem(); };
    dayL.onClick = i => { day = i; showDay(); };
  };
  if (hasPin() && !revealed) handler.hold = revealHold(() => showBrowse(kind, cats[current] ? cats[current].id : null));
  const keep = live && resume && playing;
  show(root, handler, keep);
  handlerClicks();
  if (!live) $('.vview').addEventListener('click', () => { activate('view'); handler.key('ok'); }); // ponteiro do Magic Remote
  // filtra enquanto digita (espera 300 ms parar); OK do teclado desce para o resultado
  let typing = 0;
  const filter = toList => { clearTimeout(typing); searchQ[kind] = hin.value.trim(); load(current, toList, 0, true); };
  hin.addEventListener('input', () => { clearTimeout(typing); typing = setTimeout(() => filter(false), 300); });
  hin._enter = () => filter(true);
  hin.addEventListener('click', () => activate('input'));

  const si = cats.findIndex(c => c.id === startKey), start = si >= 0 ? si : live ? 0 : 2; // TV ao vivo abre em "Todos"; filmes/séries na 1ª categoria do provedor
  catL.set(cats, start);
  if (!live) { catL.first = Math.max(0, start - 2); catL.draw(true); } // set() põe a categoria no topo e esconde Favoritos/Buscar
  vodRight();
  activate('cats');
  load(start, startPos >= 0, Math.max(0, startPos), true);
  if (live) {
    dayL.set(dayStarts, day); dayL.mark = day; dayL.draw(true);
    if (cats[current] && cats[current].id !== ALL) {
      if (itemCache['live:' + ALL]) showCounts(itemCache['live:' + ALL]);
      else { const id = screenId; api.items('live', null).then(all => { if (id === screenId) { itemCache['live:' + ALL] = all; showCounts(all); } }).catch(() => {}); }
    }
    if (keep) { // voltando da tela cheia: a telinha continua com o mesmo canal
      const go = () => { const i = playing ? items.findIndex(it => it.id === playing.id) : -1; if (i >= 0) { itemL.idx = i; startPreview(i); activate('items'); epgFor(itemL.cur()); } else stopVideo(); };
      if (items.length) go(); else afterLoad = go; // lista ainda carregando (cache apagado ao sair do app): espera ela
    }
  }
}

/* ---------- detalhes de filme e série ---------- */
/** Fundo com a imagem do título bem escura + pôster à esquerda + coluna de informações. */
function detailFrame(poster) {
  const root = screenEl();
  root.innerHTML = '<img class="dback"><img class="dposter"><div class="dinfo"></div>';
  const p = root.querySelector('.dposter');
  if (poster) p.src = poster;
  p.onerror = () => p.removeAttribute('src');
  return root;
}
function meta(i) {
  const r = Number(i.rating);
  return [String(i.releasedate || i.releaseDate || i.release_date || '').slice(0, 4), i.duration || '', i.genre || '', r > 0 ? '★ ' + r.toFixed(1).replace('.', ',') : '']
    .filter(Boolean).join('   ·   ');
}
function backdrop(root, i) { const b = i.backdrop_path; const u = Array.isArray(b) ? b[0] : b; if (u) root.querySelector('.dback').src = u; }

function showMovie(item, back) {
  const root = detailFrame(item.icon), info = root.querySelector('.dinfo');
  info.innerHTML = '<h1 class="two"></h1><div class="dmeta"></div><div class="dplot six">Carregando informações…</div><div class="dpeople"></div><div class="dbtns"></div>';
  info.querySelector('h1').textContent = item.name;
  const btns = info.querySelector('.dbtns');
  const watch = fromStart => play('movie', [item], 0, fromStart ? 0 : -1, () => showMovie(item, back));
  const button = (html, go) => { const b = el('div', 'btn f', html); b.addEventListener('click', go); btns.appendChild(b); return b; };
  const pos = position('movie', item.id);
  let first;
  if (pos > 0) { first = button(ic('play') + '  Continuar de ' + clock(pos), () => watch(false)); button('Do início', () => watch(true)); }
  else first = button(ic('play') + '  Assistir', () => watch(true));
  favButton(button, item, 'movie');
  const id = show(root, focusScreen(root, first, back));
  api.vodInfo(item.id).then(i => {
    if (id !== screenId) return;
    info.querySelector('.dmeta').textContent = meta(i);
    info.querySelector('.dplot').textContent = i.plot || i.description || 'Sem sinopse.';
    info.querySelector('.dpeople').textContent = [i.director ? 'Direção: ' + i.director : '', (i.cast || i.actors) ? 'Elenco: ' + (i.cast || i.actors) : ''].filter(Boolean).join('\n');
    backdrop(root, i);
  }).catch(() => { if (id === screenId) info.querySelector('.dplot').textContent = 'Não foi possível carregar a sinopse.'; });
}

/** "☆ Favoritar" / "★ Favorito" nos detalhes de filme e série (aparece em Favoritos na tela do catálogo). */
function favButton(button, item, kind) {
  const label = () => isFav(item.id, kind) ? '★  Favorito' : '☆  Favoritar';
  const b = button(label(), () => { toggleFav(item, kind); b.innerHTML = label(); });
  return b;
}

function showSeries(item, back, startSeason, startEp) {
  const root = detailFrame(item.icon), info = root.querySelector('.dinfo');
  info.innerHTML = '<div class="dtop"><h1 class="one"></h1></div><div class="dmeta"></div><div class="dplot three">Carregando informações…</div><div class="seasons"></div><div class="deps"></div>';
  info.querySelector('h1').textContent = item.name;
  // Favoritar ao lado do nome: ▲ das temporadas chega nele (no fim da fila ficaria longe em série com muitas temporadas)
  const favB = favButton((html, go) => { const b = el('div', 'btn dfav', html); b.addEventListener('click', go); info.querySelector('.dtop').appendChild(b); return b; }, item, 'series');
  const sRow = info.querySelector('.seasons');
  const epL = new List({ h: 106, cls: 'pl', render: e => '<span class="t">' + esc(e.label) + '</span>' });
  info.querySelector('.deps').appendChild(epL.el);
  let seasons = [], season = 0, sFocus = -1; // sFocus: -1 episódios, -2 Favoritar, >= 0 temporada
  const handler = {
    key(k) {
      if (k === 'back') return back();
      if (sFocus === -2) {
        if (k === 'down') { if (seasons.length) focusSeason(season); else if (epL.items.length) focusSeason(-1); }
        else if (k === 'ok') favB.click();
        return;
      }
      if (sFocus >= 0) {
        if (k === 'left' && sFocus > 0) focusSeason(sFocus - 1);
        else if (k === 'right' && sFocus < seasons.length - 1) focusSeason(sFocus + 1);
        else if (k === 'down' && epL.items.length) focusSeason(-1);
        else if (k === 'up') focusSeason(-2);
        else if (k === 'ok') showSeason(sFocus, true, 0);
        return;
      }
      if (k === 'up' && !epL.move(-1)) return focusSeason(seasons.length ? season : -2);
      if (k === 'down') return epL.move(1);
      if (k === 'chup' || k === 'chdown') return epL.move((k === 'chup' ? -1 : 1) * epL.page());
      if (k === 'ok' && epL.cur()) { const s = season; play('series', seasons[s].eps, epL.idx, -1, at => showSeries(item, back, s, at)); }
    }
  };
  const focusSeason = i => {
    sFocus = i;
    Array.prototype.forEach.call(sRow.children, (b, k) => b.classList.toggle('on', k === i));
    favB.classList.toggle('on', i === -2);
    if (i >= 0) sRow.scrollLeft = Math.max(0, sRow.children[i].offsetLeft - 8);
    epL.active = i === -1; epL.draw();
  };
  const showSeason = (s, focusList, select) => {
    season = s;
    Array.prototype.forEach.call(sRow.children, (b, k) => { b.innerHTML = (k === s ? ic('tri', 'tri') : '') + esc(seasons[k].name); });
    seasons[s].eps.forEach(e => { const p = position('series', e.id); e.label = e.name + (p > 0 ? '     ⟲ ' + clock(p) : ''); });
    epL.set(seasons[s].eps, select);
    if (focusList) focusSeason(-1);
  };
  const id = show(root, handler);
  epL.active = true; epL.empty = ''; epL.draw(true);
  api.seriesInfo(item.id).then(r => {
    if (id !== screenId) return;
    const i = r.info;
    info.querySelector('.dmeta').textContent = meta(i);
    info.querySelector('.dplot').textContent = i.plot || 'Sem sinopse.';
    backdrop(root, i);
    seasons = r.seasons;
    if (!seasons.length) { epL.empty = 'Nenhum episódio disponível.'; epL.set([]); return; }
    seasons.forEach((s, k) => { const b = el('div', 'btn sbt'); b.addEventListener('click', () => showSeason(k, true, 0)); sRow.appendChild(b); });
    showSeason(Math.max(0, Math.min(startSeason || 0, seasons.length - 1)), true, startEp || 0);
  }).catch(e => { if (id === screenId) info.querySelector('.dplot').textContent = e.message; });
}

/* ---------- player tela cheia ---------- */
let playCtx = null; // { kind, list, at } do que está na tela cheia (posição salva ao sair)
function savePosition() {
  const c = playCtx;
  if (!c || c.kind === 'live' || !playing || !video.duration || !isFinite(video.duration)) return;
  const pos = video.currentTime * 1000, d = video.duration * 1000;
  setPosition(c.kind, c.list[c.at].id, pos > 60000 && pos < d - 180000 ? pos : 0); // perto do começo ou do fim = "não começado"
}

/** startMs: -1 = continua de onde parou (filmes/séries), 0 = do início. back(at) volta para quem chamou. keep: telinha já toca o canal. */
function play(kind, list, index, startMs, back, keep) {
  const live = kind === 'live';
  const root = screenEl('black');
  root.innerHTML = '<div class="pov"></div><div class="pst"></div>';
  const ov = root.querySelector('.pov'), st = root.querySelector('.pst');
  let at = index, hideT = 0, tickT = 0, panelOpen = false;
  const leave = () => {
    savePosition(); playCtx = null; clearTimeout(hideT); clearTimeout(tickT);
    back(at, list); // ao vivo: a telinha continua o mesmo vídeo (e a gravação, se ligada)
  };
  // ao vivo gravando: a janela que dá para voltar é video.seekable (cresce até 10 min); "ao vivo" = perto do fim dela
  const shifting = () => live && playing && playing.shift;
  const edge = () => { const s = video.seekable; return s.length ? s.end(s.length - 1) : 0; };
  // quanto está atrás do ao vivo: soma o que a pessoa voltou/adiantou e o tempo pausado (medir pelo fim da gravação não dá:
  // o player relê a lista em intervalos irregulares e o fim anda aos saltos de até ~20 s)
  let lateS = 0, pausedAt = 0;
  const away = () => lateS > 0 || pausedAt > 0;
  const late = () => lateS + (pausedAt ? (Date.now() - pausedAt) / 1000 : 0);
  const goLive = () => { lateS = 0; pausedAt = 0; if (video.seekable.length) video.currentTime = Math.max(0, edge() - 4); video.play(); showOverlay(); };
  const shiftBy = d => {
    const s = video.seekable, from = video.currentTime || 0;
    if (!s.length) return showOverlay();
    if (d > 0 && late() - d < 5) return goLive();
    const to = Math.max(s.start(0), from + d);
    lateS -= to - from;
    video.currentTime = to;
    showOverlay();
  };
  const togglePause = () => {
    if (!video.paused) { pausedAt = Date.now(); video.pause(); }
    else { if (pausedAt) { lateS += (Date.now() - pausedAt) / 1000; pausedAt = 0; } video.play(); }
    showOverlay();
  };

  // gravação desligada por padrão: o botão Gravar reabre o canal pelo serviço (services/shift); trocar de canal desliga
  const lowOn = () => store.get('lowDelay', false);
  const lowBtn = () => ['low', 'Atraso: ' + (lowOn() ? 'menor' : 'normal'), () => {
    store.set('lowDelay', !lowOn()); selKey = 'low'; lateS = 0; pausedAt = 0;
    playUrls(list[at].id, api.liveUrls(list[at].id), 0, playing && playing.rec); placeVideo({ x: 0, y: 0, w: 1920, h: 1080 }); showOverlay();
  }];
  const record = on => { selKey = on ? 'pp' : 'rec'; lateS = 0; pausedAt = 0; playUrls(list[at].id, api.liveUrls(list[at].id), 0, on); placeVideo({ x: 0, y: 0, w: 1920, h: 1080 }); showOverlay(); };
  // barra de botões embaixo (ao vivo): ◀ ▶ escolhem, OK aperta; o controle com ponteiro clica direto
  let selKey = 'rec';
  const buttons = () => (shifting() ? [
    ['rew', ic('left') + '  10 s', () => shiftBy(-10)],
    ['pp', video.paused ? ic('play') + '  Play' : ic('pause') + '  Pausar', togglePause],
    ['ff', '10 s  ' + ic('right'), () => shiftBy(10)],
    ['live', '●  Ao vivo', goLive],
  ].concat(lowOn() ? [] : [['stop', '■  Parar', () => record(false)]]) : [['rec', '●  Gravar', () => record(true)]].concat(bgShift ? [['bgstop', '■  Parar gravação de ' + bgName(), () => { stopBgShift(); showOverlay(); }]] : [])).concat([lowBtn(),
    ['fav', (isFav(list[at].id) ? '★' : '☆') + '  Favoritar', () => { toggleFav(list[at]); showOverlay(); }],
    ['epg', 'Programação', () => showGuide()],
    ['trk', 'Áudio e legendas', () => showTracks()],
  ]);
  const bgName = () => { const c = bgShift && list.filter(x => x.id === bgShift.id)[0]; return c ? c.name : 'outro canal'; };
  const press = () => { const b = buttons().filter(x => x[0] === selKey)[0]; if (b) b[2](); };
  const moveSel = d => { const b = buttons().map(x => x[0]); selKey = b[Math.max(0, Math.min(b.length - 1, b.indexOf(selKey) + d))]; showOverlay(); };

  const showOverlay = () => {
    const it = list[at];
    clearTimeout(hideT); clearTimeout(tickT);
    if (live) {
      const rec = shifting(), bs = buttons();
      if (!bs.some(b => b[0] === selKey)) selKey = rec ? 'pp' : 'rec';
      ov.innerHTML = '<div class="o1"></div><div class="o2"></div><div class="pctl">' + (rec ? '<div class="obar"><i></i></div><div class="oclk"></div>' : bgShift ? '<div class="oclk">●  Gravando ' + esc(bgName()) + ' em segundo plano</div>' : '') +
        '<div class="cbtns"></div><div class="o3">CH+ / CH−  trocar canal     ' + ic('left') + ' ' + ic('right') + '  escolher     OK  apertar     VOLTAR  ' + (rec ? 'ao vivo / sair' : 'sair') + '</div></div>';
      const row = ov.querySelector('.cbtns');
      bs.forEach(b => {
        const e = el('div', 'btn' + (b[0] === selKey ? ' on' : ''));
        e.innerHTML = b[1];
        e.addEventListener('click', () => { selKey = b[0]; b[2](); });
        row.appendChild(e);
      });
    }
    if (live && shifting()) {
      const tick = () => {
        const s = video.seekable, bar = ov.querySelector('.obar i'), c = ov.querySelector('.oclk');
        if (!bar) return;
        const a = s.length ? s.start(0) : 0, z = edge();
        bar.style.width = (z > a ? ((video.currentTime || 0) - a) * 100 / (z - a) : 100) + '%';
        c.innerHTML = (video.paused ? ic('pause') + '  Pausado     ' : '') + (!away() ? '●  Ao vivo' : '−' + clock(late() * 1000) + '  atrás do ao vivo') + '     ·     guarda até 10 min';
        tickT = setTimeout(tick, 1000);
      };
      tick();
    }
    if (live) {
      ov.querySelector('.o1').textContent = (at + 1) + '   ' + it.name + (isFav(it.id) ? '   ★' : '');
      const id = it.id;
      loadEpg(id, 4, l => { if (list[at] && list[at].id === id && ov.querySelector('.o2')) ov.querySelector('.o2').textContent = nowNext(l); });
    } else {
      ov.innerHTML = '<div class="o1 one"></div><div class="obar"><i></i></div><div class="oclk"></div><div class="o3">' + ic('left') + ' −15 s     ' + ic('right') + ' +30 s     ' +
        ic('up') + ' ' + ic('down') + '  ±5 min     OK  pausar     segure OK  áudio e legendas     VOLTAR  sair' + (list.length > 1 ? '     CH+ / CH−  episódio' : '') + '</div>';
      ov.querySelector('.o1').textContent = it.name;
      const tick = () => {
        const d = video.duration && isFinite(video.duration) ? video.duration * 1000 : 0, p = (video.currentTime || 0) * 1000;
        const bar = ov.querySelector('.obar i'), c = ov.querySelector('.oclk');
        if (!bar) return;
        bar.style.width = (d ? p * 100 / d : 0) + '%';
        c.innerHTML = (video.paused ? ic('pause') + '  Pausado     ' : '') + clock(p) + (d ? '  /  ' + clock(d) : '');
        tickT = setTimeout(tick, 1000);
      };
      tick();
    }
    ov.style.display = 'block';
    if ((live && !shifting()) || !video.paused) hideT = setTimeout(() => { ov.style.display = 'none'; clearTimeout(tickT); }, 4000); // pausado, a barra fica
  };
  const start = ms => {
    const it = list[at];
    lateS = 0; pausedAt = 0;
    playCtx = { kind: kind, list: list, at: at };
    let urls;
    if (live) { if (!isBlocked(it)) store.set('last:' + acct(), it); urls = api.liveUrls(it.id); }
    else { urls = [api.fileUrl(kind, it)]; if (ms === 0) setPosition(kind, it.id, 0); }
    showOverlay();
    if (!(keep && playing && playing.id === it.id)) playUrls(it.id, urls, live ? 0 : position(kind, it.id)); // veio da telinha: continua
    keep = false;
    placeVideo({ x: 0, y: 0, w: 1920, h: 1080 });
  };
  const zapBy = d => {
    if (list.length < 2) return showOverlay();
    savePosition();
    at = (at + d + list.length) % list.length;
    start();
  };
  const seek = s => { if (video.duration) video.currentTime = Math.max(0, Math.min(video.duration - 1, video.currentTime + s)); showOverlay(); };
  const handler = {
    holdMs: 1000,
    hold() { showTracks(); },
    key(k) {
      if (k === 'back') return shifting() && away() ? goLive() : leave(); // atrasado: VOLTAR vai ao vivo
      if (live) {
        if (k === 'chup') return zapBy(1); // canal só pelos botões CH+ / CH− do controle
        if (k === 'chdown') return zapBy(-1);
        if (k === 'menu' || k === 'blue') return showTracks();
        if (shifting()) { // teclas de mídia do controle continuam valendo
          if (k === 'play' || k === 'pause') return togglePause();
          if (k === 'rew') return shiftBy(-10);
          if (k === 'ff') return shiftBy(10);
        }
        if (ov.style.display !== 'block') return showOverlay(); // 1º toque só mostra a barra
        if (k === 'left' || k === 'right') return moveSel(k === 'left' ? -1 : 1);
        if (k === 'ok') return press();
        if (k === 'info') return showOverlay();
        return;
      }
      if (k === 'left' || k === 'rew') return seek(-15);
      if (k === 'right' || k === 'ff') return seek(30);
      if (k === 'up') return seek(300);
      if (k === 'down') return seek(-300);
      if (k === 'chup' || k === 'chdown') return zapBy(k === 'chup' ? 1 : -1);
      if (k === 'ok' || k === 'play' || k === 'pause') { if (video.paused) video.play(); else video.pause(); return showOverlay(); }
      if (k === 'info') return showOverlay();
      if (k === 'menu' || k === 'blue') return showTracks();
    }
  };

  /** Painel com a programação do canal atual (▶ no player). */
  const showGuide = () => {
    const ch = list[at];
    ov.style.display = 'none';
    const node = el('div', 'pside');
    node.innerHTML = '<div class="stitle">Programação</div><div class="sname"></div><div class="sstat">Carregando programação…</div><div class="slist"></div><div class="sdesc"></div><div class="sfoot">VOLTAR fecha</div>';
    node.querySelector('.sname').textContent = ch.name;
    const L = new List({ h: 106, cls: 'pl', render: p => '<span class="t">' + hhmm(p.start) + '–' + hhmm(p.end) + '   ' + esc(p.title) + '</span>' });
    L.active = true;
    node.querySelector('.slist').appendChild(L.el);
    L.onMove = p => { node.querySelector('.sdesc').textContent = p.desc || ''; };
    openModal(node, { key(k) {
      if (k === 'back') return closeModal();
      if (k === 'up' || k === 'down') L.move(k === 'up' ? -1 : 1);
      if (k === 'chup' || k === 'chdown') L.move((k === 'chup' ? -1 : 1) * L.page());
    } });
    loadEpg(ch.id, 24, progs => {
      if (modal == null || modal.node !== node) return;
      if (!progs.length) { node.querySelector('.sstat').textContent = 'Este canal não tem programação no servidor.'; return; }
      node.querySelector('.sstat').style.display = 'none';
      const now = Date.now();
      L.mark = progs.findIndex(p => now >= p.start && now < p.end);
      L.set(progs, Math.max(0, L.mark));
      node.querySelector('.sdesc').textContent = progs[L.idx].desc || '';
    });
  };

  /** Painel de áudio e legendas (segurar OK ou o botão azul). */
  const showTracks = () => {
    ov.style.display = 'none';
    const t = tracks();
    const node = el('div', 'pside tracks');
    let h = '<div class="stitle">Áudio</div>';
    if (!t.audio.length) h += '<div class="snote">Faixas ainda carregando. Tente de novo em instantes.</div>';
    t.audio.forEach((a, i) => { h += '<div class="opt f" data-a="' + i + '">' + (a.on ? ic('check') : '<i class="sp"></i>') + '   ' + esc(a.name) + '</div>'; });
    h += '<div class="stitle">Legendas</div><div class="opt f" data-off="1">' + (!t.textOn ? ic('check') : '<i class="sp"></i>') + '   Desligadas</div>';
    t.text.forEach((a, i) => { h += '<div class="opt f" data-s="' + i + '">' + (a.on ? ic('check') : '<i class="sp"></i>') + '   ' + esc(a.name) + '</div>'; });
    if (!t.text.length) h += '<div class="snote">Este título não tem legendas.</div>';
    node.innerHTML = h + '<div class="sfoot">VOLTAR fecha</div>';
    node.querySelectorAll('.opt').forEach(o => o.addEventListener('click', () => {
      const a = o.getAttribute('data-a'), s = o.getAttribute('data-s');
      if (a != null) { t.audio[a].pick(); store.set('audioLang', t.audio[a].lang || null); }
      else if (s != null) { t.text[s].pick(); store.set('subLang', t.text[s].lang || null); }
      else { t.off(); store.set('subLang', 'off'); }
      closeModal();
    }));
    const opts = Array.prototype.slice.call(node.querySelectorAll('.opt'));
    const f = focusScreen(node, opts.filter(o => o.querySelector('svg'))[0] || opts[0], closeModal); // começa no escolhido
    openModal(node, { key: f.key });
  };

  show(root, handler, keep);
  onVideoState = s => {
    if (s === '' && shifting() && ov.style.display === 'block' && !ov.querySelector('.obar')) showOverlay();
    if (s !== 'fail') { st.textContent = s; return; }
    st.textContent = live ? 'Não foi possível reproduzir este canal.\nCH+ / CH− para outro canal  ·  VOLTAR para sair' : 'Não foi possível reproduzir este conteúdo.\nVOLTAR para sair';
  };
  onVideoEnd = () => {
    if (live) return;
    setPosition(kind, list[at].id, 0);
    if (kind === 'series' && at < list.length - 1) { at++; start(); } // próximo episódio
    else { playCtx = null; back(at, list); }
  };
  start(startMs);
}
function nowNext(list) {
  const now = Date.now(), cur = list.filter(p => now >= p.start && now < p.end)[0];
  const next = list.filter(p => p.start >= (cur ? cur.end : now))[0];
  return [cur ? 'Agora   ' + hhmm(cur.start) + '–' + hhmm(cur.end) + '   ' + cur.title : '', next ? 'A seguir   ' + hhmm(next.start) + '   ' + next.title : '']
    .filter(Boolean).join('\n') || 'Sem programação disponível para este canal.';
}

/* ---------- busca ---------- */
const MAX_RESULTS = 300;
let lastQuery = '', lastSearchPos = -1;
function showSearch(back) {
  if (!api) return showLogin();
  if (typeof back !== 'function') back = showHome;
  const again = () => showSearch(back);
  const root = screenEl();
  root.innerHTML = '<div class="shead"><div class="logo">' + LOGO + '</div><b>Buscar</b></div>' +
    '<input class="fld sinput" placeholder="Buscar canal, filme ou série" autocomplete="off" spellcheck="false"><div class="sstatus">Digite pelo menos 2 letras.</div><div class="sres"></div>';
  const input = root.querySelector('input'), status = root.querySelector('.sstatus');
  const L = new List({ h: 106, cls: 'pl', render: r => ic(r.k === 'live' ? 'play' : r.k === 'movie' ? 'movie' : 'series', 'kind') + '<span class="t">' + esc(r.it.name) + '</span>' });
  root.querySelector('.sres').appendChild(L.el);
  let found = [], inList = false;
  const focusInput = () => { inList = false; input.classList.add('on'); L.active = false; L.draw(); };
  const focusList = () => { if (!found.length) return; inList = true; input.classList.remove('on'); L.active = true; L.draw(); };

  const search = (q, toList) => {
    if (q !== lastQuery) lastSearchPos = -1;
    lastQuery = q;
    const words = norm(q).split(' ').filter(Boolean);
    if (q.trim().length < 2) { found = []; L.set([]); status.textContent = 'Digite pelo menos 2 letras.'; return; }
    if (!searchIndex) {
      status.textContent = 'Carregando o catálogo completo (só na primeira busca, pode levar alguns segundos)…';
      const id = screenId;
      Promise.all(KIND_ORDER.map(k => Promise.all([
        catCache[k] ? catCache[k] : api.categories(k),       // nomes das categorias: sugestão do controle parental
        itemCache[k + ':' + ALL] ? itemCache[k + ':' + ALL] : api.items(k, null)
      ]))).then(r => {
        r.forEach((x, i) => { catCache[KIND_ORDER[i]] = x[0]; itemCache[KIND_ORDER[i] + ':' + ALL] = x[1]; });
        searchIndex = [];
        r.forEach((x, i) => x[1].forEach(it => searchIndex.push({ k: KIND_ORDER[i], it: it, n: norm(it.name) })));
        if (id === screenId) search(input.value, toList);
      }).catch(e => { if (id === screenId) status.textContent = e.message; });
      return;
    }
    const hide = hasPin() && !revealed, bl = hide ? blockedKeys() : {};
    const hits = [];
    for (let i = 0; i < searchIndex.length && hits.length <= MAX_RESULTS; i++) {
      const s = searchIndex[i];
      if (bl[s.k + ':' + s.it.cat] || (hide && ADULT.test(s.n))) continue;
      if (words.every(w => s.n.indexOf(w) >= 0)) hits.push(s);
    }
    found = hits.slice(0, MAX_RESULTS);
    L.set(found, Math.max(0, Math.min(lastSearchPos, found.length - 1)));
    status.innerHTML = !found.length ? 'Nada encontrado para “' + esc(q.trim()) + '”.'
      : hits.length > MAX_RESULTS ? 'Mais de ' + MAX_RESULTS + ' resultados: digite mais letras para refinar.'
        : plural(found.length, 'resultado', 'resultados') + '    ·    ' + ic('play') + ' canal    ' + ic('movie') + ' filme    ' + ic('series') + ' série';
    if (toList && found.length) focusList(); else L.draw();
  };
  let typing = 0;
  input.addEventListener('input', () => { clearTimeout(typing); typing = setTimeout(() => search(input.value), 450); });
  input._enter = () => { clearTimeout(typing); search(input.value, true); };
  const openHit = () => {
    const r = found[L.idx];
    if (!r) return;
    lastSearchPos = L.idx;
    if (r.k === 'live') { const chans = found.filter(x => x.k === 'live').map(x => x.it); play('live', chans, chans.indexOf(r.it), -1, again); }
    else if (r.k === 'movie') showMovie(r.it, again);
    else showSeries(r.it, again);
  };
  L.onClick = openHit;
  show(root, {
    key(k) {
      if (k === 'back') return back();
      if (!inList) { if (k === 'ok') input.focus(); else if (k === 'down') focusList(); return; }
      if (k === 'up' && !L.move(-1)) return focusInput();
      if (k === 'down') return L.move(1);
      if (k === 'chup' || k === 'chdown') return L.move((k === 'chup' ? -1 : 1) * L.page());
      if (k === 'ok') return openHit();
    }
  });
  input.value = lastQuery;
  focusInput();
  if (lastQuery.trim().length >= 2 && lastSearchPos >= 0) search(lastQuery, true); // voltando de um resultado
  else { if (lastQuery) search(lastQuery); input.focus(); }
}

