/** Teste de conexão no painel das Configurações: cada etapa aparece assim que termina. */
function runNetTest(col) {
  const id = screenId;
  const step = title => { const r = el('div', 'kv step', '<b></b><span>…</span>'); r.querySelector('b').textContent = title; col.appendChild(r); return r.querySelector('span'); };
  const host = api.base.replace(/^https?:\/\//, '').split(/[:/]/)[0];
  const dnsV = step('Endereço'), pingV = step('Servidor'), acctV = step('Conta'), speedV = step('Velocidade');
  col.appendChild(el('div', 'stx small', 'OK de novo testa outra vez.'));
  const put = (v, t, ok) => { if (id !== screenId) return; v.textContent = t; v.className = ok === false ? 'bad' : ''; };
  put(dnsV, host + '   (DNS da TV)');
  const t0 = Date.now();
  api.login().then(() => {
    const ms = Date.now() - t0, i = api.info;
    put(pingV, 'respondeu em ' + ms + ' ms' + (ms < 400 ? '  ·  rápido' : ms < 1500 ? '  ·  normal' : '  ·  lento'), ms < 1500);
    put(acctV, ['ativa', (i.active_cons || '0') + ' de ' + (i.max_connections || '?') + ' conexões em uso', accountLine().split('  ·  ')[1]].join('  ·  '));
  }).catch(e => { put(pingV, e.message, false); put(acctV, '—', false); }).then(() => {
    let ch = lastCh();
    if (!ch) for (const k in itemCache) if (k.indexOf('live:') === 0 && itemCache[k].length) { ch = itemCache[k][0]; break; }
    if (!ch) return put(speedV, 'Assista um canal antes para medir a velocidade.', false);
    put(speedV, 'medindo com ' + ch.name + ' (8 s)…');
    const url = api.path('live') + ch.id + '.ts';
    let bytes = 0;
    const began = Date.now();
    fetch(url).then(r => {
      if (!r.ok || !r.body) throw new Error('O servidor respondeu ' + r.status + '.');
      const rd = r.body.getReader();
      const pump = () => rd.read().then(x => {
        if (x.done || Date.now() - began >= 8000) { rd.cancel(); return; }
        bytes += x.value.length; return pump();
      });
      return pump();
    }).then(() => {
      const mbps = bytes * 8 / 1000 / Math.max(1, Date.now() - began);
      const v = mbps >= 15 ? 'ótima para Full HD e 4K' : mbps >= 8 ? 'boa para Full HD' : mbps >= 4 ? 'dá para HD, pode travar em Full HD' : 'fraca: deve travar';
      put(speedV, mbps.toFixed(1).replace('.', ',') + ' Mbps  ·  ' + v, mbps >= 4);
    }).catch(e => put(speedV, e.message, false));
  });
}

