    option('edit', 'Trocar PIN', defaultPin() ? 'Ainda é o padrão 0000' : 'Criar um PIN novo', () => createPin(showParental));
    option('x', 'Desligar controle parental', 'Apaga o PIN e as categorias escolhidas; tudo fica liberado', () => {
      setPin(null); store.del('blocked:' + acct()); store.set('allowed:' + acct(), []); pinOk = false; revealed = false; showParental();
    });
  }
  show(root, focusScreen(root, box.firstChild, showSettings));
}
function showBlocked() {
  pickCategories('Categorias bloqueadas', 'OK bloqueia ou libera   ·   as categorias adultas já vêm sugeridas', blockedKeys, set => {
    const keys = Object.keys(set).filter(k => set[k]);
    store.set('blocked:' + acct(), keys);
    store.set('allowed:' + acct(), adultKeys().filter(k => !set[k])); // adulta desmarcada de propósito fica liberada
  }, showParental);
}
/** Todas as categorias (canais, filmes e séries); OK marca ou desmarca e salva na hora. */
/** start é função: só pode ser lida DEPOIS de baixar todas as categorias (senão as adultas de filmes/séries
 *  aparecem desmarcadas e o 1º toque as grava como liberadas). */
function pickCategories(title, hint, start, save, back) {
  const missing = KIND_ORDER.filter(k => !catCache[k]);
  if (missing.length) {
    const msg = loadingScreen('Carregando categorias…', back), id = screenId;
    Promise.all(missing.map(k => api.categories(k))).then(r => {
      r.forEach((l, i) => { catCache[missing[i]] = l; });
      if (id === screenId) pickCategories(title, hint, start, save, back);
    }).catch(e => { msg.textContent = e.message + '\n\nVOLTAR'; });
    return;
  }
  const set = Object.assign({}, start());
  const entries = [];
  KIND_ORDER.forEach(k => { entries.push({ head: KINDS[k].title }); catCache[k].forEach(c => entries.push({ key: k + ':' + c.id, name: c.name })); });
  const root = screenEl();
  root.innerHTML = '<div class="pg"><div class="pgt">' + esc(title) + '</div><div class="pgh">' + esc(hint) + '</div><div class="pick"></div></div>';
  const L = new List({ h: 78, cls: 'pl small', render: e => e.head ? '<span class="t head">———  ' + esc(e.head) + '  ———</span>'
    : (set[e.key] ? ic('lock', 'lk') : '<i class="sp"></i>') + '<span class="t">' + esc(e.name) + '</span>' });
  root.querySelector('.pick').appendChild(L.el);
  L.active = true;
  const flip = () => { const e = L.cur(); if (!e || !e.key) return; set[e.key] = !set[e.key]; save(set); L.draw(true); };
  L.onClick = flip;
  show(root, {
    key(k) {
      if (k === 'back') return back();
      if (k === 'up' || k === 'down') L.move(k === 'up' ? -1 : 1);
      if (k === 'chup' || k === 'chdown') L.move((k === 'chup' ? -1 : 1) * L.page());
      if (k === 'ok') flip();
    }
  });
  L.set(entries, 1);
}

/* ---------- app escondido (Home da TV, outro app): para o vídeo; na volta bloqueadas se escondem e tudo é relido ---------- */
let resumeVideo = null;
document.addEventListener('visibilitychange', () => {
  if (document.hidden) {
    pinOk = false; revealed = false;
    catCache = {}; itemCache = {}; searchIndex = null; // categoria/canal adulto novo já entra bloqueado
    if (playing) { savePosition(); resumeVideo = { id: playing.id, urls: playing.urls, rect: videoRect, shift: playing.shift, at: playCtx && playCtx.kind !== 'live' ? position(playCtx.kind, playCtx.list[playCtx.at].id) : 0 }; stopVideo(); }
  } else if (resumeVideo) {
    const r = resumeVideo; resumeVideo = null;
    if (r.rect) { playUrls(r.id, r.urls, r.at, r.shift); placeVideo(r.rect); }
  }
});

/* ---------- novidades: aviso na 1ª abertura depois de atualizar ---------- */
/** O que mudou em cada versão (a do boot.js). Mais nova primeiro. */
const NOVIDADES = {
  '0.9.3': [
    'Filmes e Séries com o mesmo visual da TV ao vivo',
    'Favoritos e Buscar na coluna da esquerda, também em Filmes e Séries',
    'Favoritar filmes e séries: botão Favoritar nos detalhes ou tecla amarela na lista',
    'Busca na barra de cima: a lista vai filtrando enquanto você digita (só canais, só filmes ou só séries)',
    'Botão Grade/Lista na própria tela de Filmes e Séries',
    'O app se atualiza sozinho ao abrir, sem precisar instalar de novo',
    'Este aviso com as novidades depois de cada atualização'
  ]
};
function verNum(v) { return String(v).split('.').map(n => +n || 0); }
function newer(a, b) { a = verNum(a); b = verNum(b); for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i] > b[i]; return false; }
let news = [];
/** Calcula uma vez ao abrir; a 1ª instalação (sem lista ainda) não mostra nada. */
function loadNews(hasAccount) {
  const seen = store.get('seen', null);
  if (seen === VERSION) return;
  store.set('seen', VERSION);
  if (!seen && !hasAccount) return;
  news = Object.keys(NOVIDADES).filter(v => seen ? newer(v, seen) && !newer(v, VERSION) : v === VERSION)
    .reduce((l, v) => l.concat(NOVIDADES[v]), []);
}
function showNews() {
  if (!news.length) return;
  const n = news; news = [];
  menuBox('Novidades da versão ' + VERSION, n.map(t => '•  ' + t).join('\n'), [['OK']]);
}

/* ---------- início ---------- */
(function boot() {
  const a = store.get('account', null);
  loadNews(!!a);
  if (!a || !a.pass) return showLogin();
  connect(a.server, a.user, a.pass);
})();

