.pov .o3 { font-size: 32px; color: var(--lilac); margin-top: 16px; white-space: pre; }
.pov .o3 .ic { width: .8em; height: .8em; }
.obar { height: 16px; background: #fff; margin-top: 28px; border-radius: 2px; overflow: hidden; }
.obar i { display: block; height: 100%; background: var(--violet); }
.oclk { font-size: 36px; margin-top: 16px; }
.pctl { position: fixed; left: 0; right: 0; bottom: 0; padding: 120px 96px 48px; background: linear-gradient(transparent, rgba(0, 0, 0, .9)); }
.pctl .obar { margin-top: 0; }
.cbtns { margin-top: 24px; white-space: nowrap; }
.cbtns .btn { font-size: 28px; padding: 14px 24px; margin-right: 14px; }
.cbtns .btn .ic { width: 1em; height: 1em; }
.pst {
  position: absolute; z-index: 3; left: 0; right: 0; top: 0; bottom: 0; display: flex; align-items: center; justify-content: center;
  font-size: 44px; text-align: center; white-space: pre-line; text-shadow: 0 0 8px #000; pointer-events: none;
}

/* painéis do player (programação, áudio e legendas) */
.modal { z-index: 5; }
.pside {
  position: absolute; right: 0; top: 0; bottom: 0; width: 960px; padding: 56px; display: flex; flex-direction: column;
  background: linear-gradient(90deg, rgba(7, 11, 26, .8), rgba(7, 11, 26, .96));
}
.pside.tracks { width: 840px; padding: 64px 56px; overflow: hidden; display: block; }
.stitle { font-size: 44px; color: var(--lilac); font-weight: 700; padding: 24px 0 16px 12px; flex: none; }
.pside .stitle:first-child { padding-top: 0; }
.sname { font-size: 36px; font-weight: 700; padding: 8px 0 0 12px; white-space: pre; overflow: hidden; text-overflow: ellipsis; flex: none; }
.sstat { font-size: 32px; color: var(--muted); padding: 16px 12px; flex: none; }
.slist { position: relative; flex: 1; min-height: 0; margin-top: 8px; }
.slist .row { font-size: 34px; }
.sdesc { font-size: 32px; color: var(--muted); padding: 20px 12px 0; max-height: 7em; overflow: hidden; line-height: 1.3; flex: none; }
.sfoot { font-size: 30px; color: var(--muted); padding: 16px 0 0 12px; flex: none; }
.snote { font-size: 32px; color: var(--muted); padding: 0 8px 12px; }
.opt { font-size: 36px; font-weight: 700; padding: 20px 36px; margin-bottom: 16px; white-space: pre; overflow: hidden; text-overflow: ellipsis; }
.opt .sp { display: inline-block; width: 1em; }

/* teclado de PIN e diálogo */
.dim { position: absolute; left: 0; top: 0; right: 0; bottom: 0; background: rgba(0, 0, 0, .85); display: flex; align-items: center; justify-content: center; }
.pcard { background: var(--bg); border: 2px solid var(--border); border-radius: 36px; padding: 48px 72px 40px; display: flex; flex-direction: column; align-items: center; }
.ptitle { font-size: 48px; font-weight: 700; align-self: flex-start; }
.pdots { margin-top: 50px; display: flex; }
.pdots i { width: 30px; height: 30px; border: 3px solid #fff; border-radius: 50%; margin: 0 15px; }
.pdots i.on { background: #fff; }
.pmsg { width: 720px; min-height: 52px; font-size: 32px; color: var(--error); text-align: center; padding-top: 8px; }
.ppad { width: 648px; margin-top: 20px; }
.pkey { float: left; width: 192px; height: 120px; margin: 12px; display: flex; align-items: center; justify-content: center; font-size: 52px; font-weight: 700; }
.dlg { width: 1100px; background: var(--card); border: 2px solid var(--border); border-radius: 28px; padding: 48px 56px; }
.dt { font-size: 44px; font-weight: 700; }
.dm { font-size: 32px; color: var(--muted); margin: 20px 0 40px; line-height: 1.3; white-space: pre-line; }
.db { text-align: right; }
.dbtn { display: inline-block; font-size: 34px; font-weight: 700; padding: 18px 44px; margin-left: 24px; }

/* configurações */
.stt { position: absolute; left: 80px; top: 44px; font-size: 60px; font-weight: 700; }
.smenu { position: absolute; left: 80px; top: 152px; width: 600px; }
.mi {
  height: 76px; margin-bottom: 8px; display: flex; align-items: center; padding: 0 24px;
  background: var(--row); border: 2px solid var(--line); border-radius: 10px;
}
.mi b { flex: 1; font-size: 30px; white-space: pre; overflow: hidden; text-overflow: ellipsis; }
.mi span { font-size: 28px; color: var(--rmuted); margin-left: 16px; white-space: pre; }
.mi.on { background: var(--sel); border-color: #fff; color: var(--sel-text); }
.mi.on span { color: var(--sel-text); }
.spanel { position: absolute; left: 736px; right: 80px; top: 152px; }
.sh { font-size: 38px; font-weight: 700; padding: 32px 0 12px; }
.sh.first { padding-top: 0; }
.stx { font-size: 30px; color: var(--rmuted); padding-bottom: 16px; line-height: 1.3; }
.stx.small { font-size: 28px; padding-top: 12px; }
.kv {
  display: flex; align-items: flex-start; font-size: 30px; padding: 14px 24px; margin-bottom: 8px;
  background: var(--row); border: 2px solid var(--line); border-radius: 10px;
}
.kv span:first-child { flex: 1; }
.kv span:last-child { color: #c9d6f5; text-align: right; }
.kv.on { background: var(--sel); border-color: #fff; color: var(--sel-text); }
.kv.on span:last-child { color: var(--sel-text); }
.kv.mute span:last-child { color: var(--rmuted); }
.kv.step b { width: 220px; flex: none; }
.kv.step span { flex: 1; color: #fff; text-align: left; }
.kv.step span.bad { color: var(--error); }

/* páginas (listas, controle parental, escolher categorias) */
.pg { position: absolute; left: 0; top: 0; right: 0; bottom: 0; padding: 48px 88px 24px; }
.pg .logo { font-size: 56px; }
.pgt { font-size: 56px; font-weight: 700; margin-top: 28px; }
.pgh { font-size: 30px; color: var(--muted); margin: 4px 0 16px; }
.pgd { font-size: 32px; color: var(--muted); margin: 8px 0 24px; line-height: 1.35; max-width: 1700px; }
.pgn { font-size: 28px; color: var(--muted); margin-top: 36px; }
.cards { height: 760px; overflow: hidden; padding: 16px; }
.lcard {
  float: left; width: 532px; height: 320px; margin: 16px; border-radius: 36px; background: var(--tile); border: 2px solid var(--tile);
  display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 0 32px; transition: transform .12s;
}
.lcard.on { background: var(--glow); border: 6px solid #fff; transform: scale(1.05); }
.lcard .ci { width: 80px; height: 80px; color: var(--lilac); margin-bottom: 12px; }
.lcard b { font-size: 48px; white-space: pre; }
.lcard small { font-size: 30px; color: var(--muted); white-space: pre; overflow: hidden; text-overflow: ellipsis; max-width: 100%; margin-top: 4px; }
.lcard.on small { color: #fff; }
.inuse { font-size: 28px; color: #86efac; margin-top: 12px; display: flex; align-items: center; }
.inuse i { width: 16px; height: 16px; border-radius: 50%; background: #86efac; margin-right: 16px; }
.option { width: 1440px; height: 168px; margin: 12px 0 12px 8px; display: flex; align-items: center; padding: 0 36px; }
.option .oi { width: 52px; height: 52px; margin-right: 52px; }
.option b { display: block; font-size: 40px; }
.option small { font-size: 30px; color: var(--muted); }
.option.on small { color: #fff; }
.pick { position: relative; width: 1520px; height: 800px; margin-top: 8px; }

/* busca */
.shead { position: absolute; left: 80px; top: 56px; display: flex; align-items: center; }
.shead .logo { font-size: 52px; padding: 0 28px 0 12px; }
.shead b { font-size: 40px; color: var(--lilac); }
.sinput { position: absolute; left: 80px; width: 1760px; top: 160px; margin: 0; }
.sstatus { position: absolute; left: 92px; right: 80px; top: 290px; font-size: 32px; color: var(--muted); }
.sstatus .ic { width: .8em; height: .8em; }
.sres { position: absolute; left: 80px; right: 80px; top: 350px; bottom: 48px; }
.ftitle { font-size: 52px; font-weight: 700; margin-top: 24px; }
.fbtns { display: flex; gap: 32px; margin-top: 48px; }
.lh .hin { display: none; flex: 1; min-width: 0; background: none; border: none; outline: none; color: #fff; font: inherit; font-size: 32px; padding: 0; }
.lh .hin::-webkit-input-placeholder { color: var(--rmuted); }
.lh .hsi { display: none; margin-right: 18px; font-size: 28px; color: var(--rmuted); }
.lh.searching .hin, .lh.searching .hsi { display: block; }
.lh.searching .htit .ttl, .lh.searching .hsort:not(.vview) > .ic:not(.hsi), .lh.searching .hsort:not(.vview) > span { display: none; }
.lh .hb.inon { border: 4px solid var(--violet); }
